function side(){const items=[{id:"home",label:"نمای کلی اداره",url:href("overview"),icon:"⌂"},...groups.filter(g=>g.id!=="overview").map((g,i)=>({id:g.id,label:g.label,icon:["۰۱","۰۲","۰۳","۰۴","۰۵","۰۶","۰۷","۰۸"][i],children:g.items.map(id=>{const m=modules.find(x=>x.id===id);return {label:m.title,url:href(id,"bank"),active:mod.id===id}})})),{id:"back",label:"بازگشت به درگاه معاونت ۷",url:"../dashboard.html",icon:"↩"}];const nav=items.map(x=>{const active=x.id==="home"?mod.id==="overview":x.id!=="back"&&mod.group===x.id,has=!!x.children,expanded=has&&mod.group===x.id;return '<div class="d2-nav-group '+(active?"is-active ":"")+(expanded?"has-open":"")+'"><div class="d2-nav-row">'+(has?'<a class="d2-nav-link" href="'+href(x.children[0].url?groups.find(g=>g.id===x.id).items[0]:"overview")+'" data-branch="true" aria-expanded="'+expanded+'" title="'+x.label+'"><span class="d2-nav-icon">'+x.icon+'</span><span class="d2-nav-label">'+x.label+'</span></a>':'<a class="d2-nav-link" href="'+x.url+'" title="'+x.label+'"><span class="d2-nav-icon">'+x.icon+'</span><span class="d2-nav-label">'+x.label+'</span></a>')+'</div>'+(has?'<div class="d2-nav-sub '+(expanded?"is-open":"")+'">'+x.children.map(c=>'<a class="d2-nav-sub-link '+(c.active?"active":"")+'" href="'+c.url+'">'+c.label+'</a>').join("")+'</div>':'')+'</div>'}).join("");return '<aside class="dept2-sidebar menu-expanded d1-sidebar" aria-label="منوی کناری اداره اداری و پشتیبانی"><button class="d2-menu-toggle" type="button" aria-label="جمع یا باز کردن منو" aria-expanded="true"><span></span><span></span><span></span></button><div class="d2-side-brand"><span class="d2-brand-mark">۰۱</span><div class="d2-brand-text"><b>اداری و پشتیبانی</b><small>معاونت ۷ · اداره تخصصی</small></div></div><nav class="d2-side-nav" aria-label="بخش‌های اداره">'+nav+'</nav></aside>'}
