function renderFleetReports(){
 const vehicles=read("vehicles"),fuel=read("vehicle-fuel"),usage=read("vehicle-usage"),maint=read("vehicle-maintenance"),inc=read("vehicle-incidents"),docs=read("vehicle-documents"),checks=read("vehicle-checklist"),costs=read("vehicle-costs");
 const sum=(a,k)=>a.reduce((n,x)=>n+(Number(x[k])||0),0);
 const otherCosts=costs.filter(x=>!["سوخت","تعمیرات","سرویس دوره‌ای"].includes(x.costType)),totalCost=sum(otherCosts,"amount")+sum(fuel,"amount")+sum(maint,"cost"),goldRates=read("vehicle-gold").filter(x=>x.type==="۱۸ عیار"&&Number(x.rate)>0).sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));const goldRateFor=x=>Number(x.goldRate)||Number(goldRates.find(g=>!x.date||String(g.date||"")<=String(x.date))?.rate)||0;
 const consumption=vehicles.map(v=>{const rows=fuel.filter(x=>(x.plate&&x.plate===v.plate)||(x.vehicleCode&&x.vehicleCode===v.vehicleCode)).sort((a,b)=>(Number(a.odometer)||0)-(Number(b.odometer)||0));let liters=0,distance=0,periodLiters=0,prev=null;rows.forEach(x=>{periodLiters+=Number(x.quantity)||0;if(x.fillType==="باک کامل"){if(prev){liters+=periodLiters;distance+=Math.max(0,(Number(x.odometer)||0)-(Number(prev.odometer)||0))}prev=x;periodLiters=0}});return {v,liters,distance,rate:distance>0?liters*100/distance:null}});
 const links=["vehicles","vehicle-fuel","vehicle-usage","vehicle-maintenance","vehicle-incidents","vehicle-documents","vehicle-checklist","vehicle-costs","vehicle-depreciation"];
 main.innerHTML='<div class="dept2-page-head"><div><span class="dept2-kicker">پایش ناوگان · اداره ۰۱</span><h1>گزارش‌های مدیریتی ناوگان</h1><p>خلاصه شاخص‌های عملیاتی براساس داده‌های ثبت‌شده در بانک‌های ناوگان</p></div></div><div class="dept2-stat-grid">'+stat("تعداد وسایل",vehicles.length)+stat("کل هزینه‌ها (تومان)",fa(totalCost))+stat("مجموع سوخت (لیتر)",fa(sum(fuel,"quantity")))+stat("پیمایش ثبت‌شده (کیلومتر)",fa(usage.reduce((n,x)=>n+(Number(x.distance)||Math.max(0,(Number(x.endKm)||Number(x.end)||0)-(Number(x.startKm)||Number(x.start)||0))),0)))+stat("حوادث ثبت‌شده",inc.length)+stat("اسناد دارای هشدار",docs.filter(x=>["منقضی‌شده","نزدیک سررسید","نیازمند بررسی"].includes(x.status)).length+checks.filter(x=>["سررسید گذشته","نزدیک سررسید","نیازمند اقدام","بررسی‌نشده"].includes(x.result||x.status)).length)+'</div><section class="dept2-panel"><div class="dept2-section-head"><div><h2>تحلیل مصرف سوخت</h2><p>مصرف هر ۱۰۰ کیلومتر فقط میان دو سوخت‌گیری باک کامل محاسبه می‌شود؛ در صورت نبود داده کافی، مقدار نمایش داده نمی‌شود.</p></div></div><div class="dept2-table-wrap"><table class="dept2-table"><thead><tr><th>وسیله</th><th>پلاک</th><th>سوخت ثبت‌شده بین دو باک کامل (لیتر)</th><th>فاصله (کیلومتر)</th><th>مصرف (لیتر در ۱۰۰ کیلومتر)</th></tr></thead><tbody>'+consumption.map(x=>'<tr><td>'+esc(x.v.vehicle||x.v.title||x.v.vehicleCode||"وسیله")+'</td><td>'+esc(x.v.plate||"—")+'</td><td>'+fa(x.liters)+'</td><td>'+fa(x.distance)+'</td><td><b>'+(x.rate===null?"داده کافی نیست":fa(x.rate.toFixed(2)))+'</b></td></tr>').join("")+'</tbody></table></div></section><section class="dept2-panel"><div class="dept2-section-head"><div><h2>هزینه به تفکیک وسیله</h2><p>جمع هزینه‌های سوخت، تعمیر و سایر هزینه‌های ثبت‌شده</p></div></div><div class="dept2-table-wrap"><table class="dept2-table"><thead><tr><th>وسیله</th><th>پلاک</th><th>سوخت</th><th>تعمیرات</th><th>سایر هزینه‌ها</th><th>جمع (تومان)</th><th>معادل طلای ۱۸ عیار (گرم)</th></tr></thead><tbody>'+vehicles.map(v=>{const match=x=>(x.plate&&x.plate===v.plate)||(x.vehicleCode&&x.vehicleCode===v.vehicleCode);const fr=fuel.filter(match),mr=maint.filter(match),cr=otherCosts.filter(match),f=sum(fr,"amount"),m=sum(mr,"cost"),c=sum(cr,"amount"),grams=[...fr.map(x=>(Number(x.amount)||0)/goldRateFor(x)),...mr.map(x=>(Number(x.cost)||0)/goldRateFor(x)),...cr.map(x=>(Number(x.amount)||0)/goldRateFor(x))].reduce((n,x)=>n+(Number.isFinite(x)?x:0),0);return '<tr><td>'+esc(v.vehicle||v.title||v.vehicleCode||"وسیله")+'</td><td>'+esc(v.plate||"—")+'</td><td>'+fa(f)+'</td><td>'+fa(m)+'</td><td>'+fa(c)+'</td><td><b>'+fa(f+m+c)+'</b></td><td>'+(grams?fa(grams.toFixed(3)):"—")+'</td></tr>'}).join("")+'</tbody></table></div></section><section class="dept2-panel"><div class="dept2-section-head"><div><h2>دسترسی به گزارش‌های موضوعی</h2></div></div><div class="dept2-module-grid">'+links.map(id=>{const m=modules.find(x=>x.id===id);return '<a class="dept2-module-card" href="'+href(id)+'"><b>'+m.title+'</b><p>'+m.desc+'</p></a>'}).join("")+'</div></section>';
}
